const searchMessages = `-- name: SearchMessages :many
SELECT m.id, m.capcode, m.alias_id, m.text, m.priority, m.heartbeat, m.sent_at, m.format,
       m.job_number, m.event_type, m.description, m.address, m.locality, m.grid_ref,
       m.paging_group, m.units, m.extra, m.parse_failed, m.address_unsplit,
       m.location_mismatch, a.name AS alias_name, COALESCE(a.ignored, false)::bool AS alias_ignored,
       t.agency, t.icon, t.colour, t.agency_profile
FROM messages m
LEFT JOIN aliases a ON a.id = m.alias_id
LEFT JOIN templates t ON t.id = a.template_id
WHERE ($1::bigint IS NULL OR m.id = $1)
  AND ($2::text IS NULL OR m.text ILIKE $2
       OR EXISTS (SELECT 1 FROM jsonb_each_text(m.extra) e WHERE e.value ILIKE $2))
  AND ($3::text IS NULL OR m.capcode = $3)
  AND ($4::text IS NULL OR a.name ILIKE $4)
  AND ($5::bigint IS NULL OR m.alias_id = $5)
  AND ($6::text IS NULL OR t.agency ILIKE $6)
  AND ($7::text IS NULL OR upper(m.paging_group) = upper($7))
  AND ($8::text IS NULL
       OR ($8 = 'none' AND m.priority IS NULL)
       OR m.priority = $8)
  AND ($9::bool IS NULL
       OR COALESCE(m.event_type = ANY($10::text[])
                   OR m.event_type LIKE ANY($11::text[]), false) = $9)
  AND ($12::text IS NULL OR m.job_number = $12)
  AND ($13::timestamptz IS NULL OR m.sent_at >= $13)
  AND ($14::timestamptz IS NULL OR m.sent_at < $14)
  AND (NOT $15::bool OR m.alias_id IS NULL)
  AND ($16::bool OR a.ignored IS NOT TRUE)
  AND (NOT $17::bool OR m.parse_failed)
  AND (NOT $18::bool OR m.address_unsplit)
  AND (NOT $19::bool OR m.location_mismatch)
  AND ($20::timestamptz IS NULL
       OR (m.sent_at, m.id) < ($20, $21::bigint))
ORDER BY m.sent_at DESC, m.id DESC
LIMIT $22::int
`

type SearchMessagesParams struct {
	OnlyID           *int64
	Q                *string
	Capcode          *string
	Alias            *string
	AliasID          *int64
	Agency           *string
	PagingGroup      *string
	Priority         *string
	CatWant          *bool
	CatCodes         []string
	CatPrefixes      []string
	JobNumber        *string
	SentFrom         *time.Time
	SentTo           *time.Time
	Unaliased        bool
	IncludeIgnored   bool
	ParseFailed      bool
	AddressUnsplit   bool
	LocationMismatch bool
	BeforeSent       *time.Time
	BeforeID         *int64
	MaxRows          int32
}

type SearchMessagesRow struct {
	ID               int64
	Capcode          string
	AliasID          *int64
	Text             string
	Priority         *string
	Heartbeat        bool
	SentAt           time.Time
	Format           *string
	JobNumber        *string
	EventType        *string
	Description      *string
	Address          *string
	Locality         *string
	GridRef          *string
	PagingGroup      *string
	Units            []string
	Extra            []byte
	ParseFailed      bool
	AddressUnsplit   bool
	LocationMismatch bool
	AliasName        *string
	AliasIgnored     bool
	Agency           *string
	Icon             *string
	Colour           *string
	AgencyProfile    *string
}

// R33. Every filter is optional (NULL = any). Keyset pagination on
// (sent_at, id), newest first. cat_want compares "event_type is in the
// category's codes" with true (that category) or false (Other).
func (q *Queries) SearchMessages(ctx context.Context, arg SearchMessagesParams) ([]SearchMessagesRow, error) {
	rows, err := q.db.Query(ctx, searchMessages,
		arg.OnlyID,
		arg.Q,
		arg.Capcode,
		arg.Alias,
		arg.AliasID,
		arg.Agency,
		arg.PagingGroup,
		arg.Priority,
		arg.CatWant,
		arg.CatCodes,
		arg.CatPrefixes,
		arg.JobNumber,
		arg.SentFrom,
		arg.SentTo,
		arg.Unaliased,
		arg.IncludeIgnored,
		arg.ParseFailed,
		arg.AddressUnsplit,
		arg.LocationMismatch,
		arg.BeforeSent,
		arg.BeforeID,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchMessagesRow
	for rows.Next() {
		var i SearchMessagesRow
		if err := rows.Scan(
			&i.ID,
			&i.Capcode,
			&i.AliasID,
			&i.Text,
			&i.Priority,
			&i.Heartbeat,
			&i.SentAt,
			&i.Format,
			&i.JobNumber,
			&i.EventType,
			&i.Description,
			&i.Address,
			&i.Locality,
			&i.GridRef,
			&i.PagingGroup,
			&i.Units,
			&i.Extra,
			&i.ParseFailed,
			&i.AddressUnsplit,
			&i.LocationMismatch,
			&i.AliasName,
			&i.AliasIgnored,
			&i.Agency,
			&i.Icon,
			&i.Colour,
			&i.AgencyProfile,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

